// Generated by integration/sync-defold-sources.mjs from core/arena.ts. Do not edit.
// The arena: a deterministic island grid with bounded reactive cover,
// plan-owned scenery, spawn points and pickup pads.
//
// The base grid is derived from a single `mapSeed` word, so static terrain never
// enters a snapshot. A bounded set of crate/sandbag cells is layered on top as
// mutable cover panels; only one health byte per panel crosses the wire. The
// fixed panel table keeps cover reactive without turning 10,800 map cells into
// mutable network state.
//
// Reactive cover is placed only on the interior of the planned island, clear
// of the coast, scenery and protected starts. The world plan alone owns
// immutable walls; cover placement must not carve inaccessible shore pockets.

import {
  MAP_CELLS,
  MAP_HEIGHT,
  MAP_WIDTH,
  COVER_MAX_HEALTH,
  MAX_COVER_PANELS,
  MAX_HAZARDS,
  MAX_PICKUPS,
  PLAYER_RADIUS,
  TILE_UNITS,
  WORLD_MIN_X,
  WORLD_MIN_Y,
} from "./constants";
import {
  PICKUP_ARMOR,
  PICKUP_HEALTH,
  PICKUP_OVERDRIVE,
  WEAPON_AUTOCANNON,
  WEAPON_MORTAR,
  WEAPON_RAILGUN,
  WEAPON_RICOCHET,
  WEAPON_SCATTER,
} from "./content";
import { mix32, mixRange } from "./fixed";
import { buildWorldPlan, WORLD_PLAN_SPAWN_COUNT, WORLD_PLAN_START_COUNT, type WorldPlan } from "./world-plan";

export const CELL_FLOOR = 0;
export const CELL_WALL = 1;
export const CELL_CRATE = 2;
export const CELL_SANDBAG = 3;

/** Border thickness, in cells. Nothing outside this is ever reachable. */
export const ARENA_BORDER_CELLS = 2;
const BORDER = ARENA_BORDER_CELLS;
/** Reactive-cover lattice pitch, in cells. */
const LATTICE = 8;
const LATTICE_COLUMNS = Math.floor(MAP_WIDTH / LATTICE);
const LATTICE_ROWS = Math.floor(MAP_HEIGHT / LATTICE);

export const SPAWN_POINT_COUNT = WORLD_PLAN_SPAWN_COUNT;

/**
 * Destructible cover stamps. Each is centred on its lattice point with a
 * small deterministic jitter; immutable walls come only from the world plan.
 */
interface Stamp {
  readonly width: number;
  readonly height: number;
  readonly cell: number;
}

const STAMPS: readonly (Stamp | undefined)[] = Object.freeze([
  undefined, // most lattice points remain open driving lanes
  undefined,
  undefined,
  undefined,
  undefined,
  Object.freeze({ width: 2, height: 2, cell: CELL_CRATE }),
  Object.freeze({ width: 5, height: 2, cell: CELL_SANDBAG }),
  Object.freeze({ width: 2, height: 5, cell: CELL_SANDBAG }),
  undefined,
]);

export interface CellPoint {
  cellX: number;
  cellY: number;
}

export interface WorldPoint {
  x: number;
  y: number;
}

export interface CircleResolution {
  x: number;
  y: number;
  hitX: boolean;
  hitY: boolean;
}

/** Caller-owned, fixed-capacity scratch for deterministic arena routing. */
export interface ArenaRouteScratch {
  readonly frontier: Int32Array;
  readonly parent: Int32Array;
  readonly visited: Uint32Array;
  generation: number;
}

export function createArenaRouteScratch(): ArenaRouteScratch {
  return {
    frontier: new Int32Array(MAP_CELLS),
    parent: new Int32Array(MAP_CELLS),
    visited: new Uint32Array(MAP_CELLS),
    generation: 0,
  };
}

/** Centre of a cell, in simulation units. */
export function cellCentreX(cellX: number): number {
  return WORLD_MIN_X + cellX * TILE_UNITS + TILE_UNITS / 2;
}

export function cellCentreY(cellY: number): number {
  return WORLD_MIN_Y + cellY * TILE_UNITS + TILE_UNITS / 2;
}

export function cellOfX(x: number): number {
  return Math.floor((x - WORLD_MIN_X) / TILE_UNITS);
}

export function cellOfY(y: number): number {
  return Math.floor((y - WORLD_MIN_Y) / TILE_UNITS);
}

export class ArenaMap {
  readonly seed: number;
  readonly plan: WorldPlan;
  readonly cells = new Uint8Array(MAP_CELLS);
  /** Spawn points and pickup pads, as cell coordinates then world units. */
  readonly spawnX = new Int32Array(SPAWN_POINT_COUNT);
  readonly spawnY = new Int32Array(SPAWN_POINT_COUNT);
  /** First-life positions are distinct from the sixteen tank-reacquisition depots. */
  readonly playerStartX = new Int32Array(WORLD_PLAN_START_COUNT);
  readonly playerStartY = new Int32Array(WORLD_PLAN_START_COUNT);
  readonly pickupX = new Int32Array(MAX_PICKUPS);
  readonly pickupY = new Int32Array(MAX_PICKUPS);
  readonly pickupKind = new Uint8Array(MAX_PICKUPS);
  /** Cell -> panel index, or -1 for static terrain/non-cover. */
  readonly coverPanelByCell = new Int16Array(MAP_CELLS);
  readonly coverX = new Int32Array(MAX_COVER_PANELS);
  readonly coverY = new Int32Array(MAX_COVER_PANELS);
  readonly coverHealth = new Uint8Array(MAX_COVER_PANELS);
  /** Number of occupied derived panels; the arrays remain MAX_COVER_PANELS wide. */
  coverPanelCount = 0;
  /** Four deterministic vent centres; hazard activity is derived from tick. */
  readonly hazardX = new Int32Array(MAX_HAZARDS);
  readonly hazardY = new Int32Array(MAX_HAZARDS);

  constructor(seed: number) {
    if (!Number.isInteger(seed) || seed < 0 || seed > 0xffff_ffff) {
      throw new RangeError("mapSeed must be an unsigned 32-bit integer");
    }
    this.seed = seed;
    this.plan = buildWorldPlan(seed);
    this.build();
  }

  index(cellX: number, cellY: number): number {
    return cellY * MAP_WIDTH + cellX;
  }

  cellAt(cellX: number, cellY: number): number {
    if (cellX < 0 || cellY < 0 || cellX >= MAP_WIDTH || cellY >= MAP_HEIGHT) return CELL_WALL;
    return this.cells[this.index(cellX, cellY)]!;
  }

  solidAt(cellX: number, cellY: number): boolean {
    // cellAt() treats the world exterior as wall. Do not index the bounded
    // cover table with an exterior coordinate: top/bottom become undefined
    // and x overflow can alias another row's mutable cover panel.
    if (cellX < 0 || cellY < 0 || cellX >= MAP_WIDTH || cellY >= MAP_HEIGHT) return true;
    if (this.cellAt(cellX, cellY) === CELL_FLOOR) return false;
    const panel = this.coverPanelByCell[this.index(cellX, cellY)]!;
    return panel < 0 || this.coverHealth[panel]! > 0;
  }

  solidAtWorld(x: number, y: number): boolean {
    return this.solidAt(cellOfX(x), cellOfY(y));
  }

  coverPanelAtWorld(x: number, y: number): number {
    const cellX = cellOfX(x);
    const cellY = cellOfY(y);
    if (cellX < 0 || cellY < 0 || cellX >= MAP_WIDTH || cellY >= MAP_HEIGHT) return -1;
    return this.coverPanelByCell[this.index(cellX, cellY)]!;
  }

  damageCoverAtWorld(x: number, y: number, damage: number): number {
    const panel = this.coverPanelAtWorld(x, y);
    if (panel < 0 || this.coverHealth[panel]! === 0) return -1;
    const remaining = Math.max(0, this.coverHealth[panel]! - Math.max(0, Math.trunc(damage)));
    this.coverHealth[panel] = remaining;
    return remaining;
  }

  /**
   * Pushes a circle out of every solid cell it overlaps, one axis at a time, and
   * reports which axes were corrected so a caller can kill or bounce that
   * component of its velocity. Axis-separated resolution is what stops a tank
   * from catching on the seam between two adjacent wall cells.
   */
  resolveCircle(x: number, y: number, radius: number, output: CircleResolution): CircleResolution {
    output.x = x;
    output.y = y;
    output.hitX = false;
    output.hitY = false;
    const centreCellX = cellOfX(x);
    const centreCellY = cellOfY(y);
    if (
      radius > 0 &&
      centreCellX >= 0 &&
      centreCellY >= 0 &&
      centreCellX < MAP_WIDTH &&
      centreCellY < MAP_HEIGHT &&
      this.solidAt(centreCellX, centreCellY)
    ) {
      // This is the exceptional recovery path for an already embedded body.
      // The ordinary single-pass contact solver cannot infer the entry face
      // from a centre inside a cell and can leave a tank inside a broad prop.
      // Search exact cell-face tangencies along four axes; no per-call staging
      // arrays or heap allocations are needed in the normal movement path.
      let bestX = x;
      let bestY = y;
      let bestDistance = Number.POSITIVE_INFINITY;
      for (let cellX = centreCellX; cellX >= 0; cellX -= 1) {
        const candidateX = WORLD_MIN_X + cellX * TILE_UNITS - radius;
        const distance = x - candidateX;
        if (distance >= bestDistance) break;
        if (this.circleOverlapsSolid(candidateX, y, radius)) continue;
        bestX = candidateX;
        bestY = y;
        bestDistance = distance;
        break;
      }
      for (let cellX = centreCellX; cellX < MAP_WIDTH; cellX += 1) {
        const candidateX = WORLD_MIN_X + (cellX + 1) * TILE_UNITS + radius;
        const distance = candidateX - x;
        if (distance >= bestDistance) break;
        if (this.circleOverlapsSolid(candidateX, y, radius)) continue;
        bestX = candidateX;
        bestY = y;
        bestDistance = distance;
        break;
      }
      for (let cellY = centreCellY; cellY >= 0; cellY -= 1) {
        const candidateY = WORLD_MIN_Y + cellY * TILE_UNITS - radius;
        const distance = y - candidateY;
        if (distance >= bestDistance) break;
        if (this.circleOverlapsSolid(x, candidateY, radius)) continue;
        bestX = x;
        bestY = candidateY;
        bestDistance = distance;
        break;
      }
      for (let cellY = centreCellY; cellY < MAP_HEIGHT; cellY += 1) {
        const candidateY = WORLD_MIN_Y + (cellY + 1) * TILE_UNITS + radius;
        const distance = candidateY - y;
        if (distance >= bestDistance) break;
        if (this.circleOverlapsSolid(x, candidateY, radius)) continue;
        bestX = x;
        bestY = candidateY;
        bestDistance = distance;
        break;
      }
      if (bestDistance === Number.POSITIVE_INFINITY) {
        // A surrounded body may have no straight exit. The bounded ring search
        // is a cold-path fallback and rejects maps without a circle-clear cell.
        this.nearestOpen(x, y, output, radius);
      } else {
        output.x = bestX;
        output.y = bestY;
      }
      output.hitX = output.x !== x;
      output.hitY = output.y !== y;
      return output;
    }
    const minCellX = cellOfX(x - radius);
    const maxCellX = cellOfX(x + radius);
    const minCellY = cellOfY(y - radius);
    const maxCellY = cellOfY(y + radius);
    for (let cellY = minCellY; cellY <= maxCellY; cellY += 1) {
      for (let cellX = minCellX; cellX <= maxCellX; cellX += 1) {
        if (!this.solidAt(cellX, cellY)) continue;
        const left = WORLD_MIN_X + cellX * TILE_UNITS;
        const bottom = WORLD_MIN_Y + cellY * TILE_UNITS;
        const nearestX = output.x < left ? left : output.x > left + TILE_UNITS ? left + TILE_UNITS : output.x;
        const nearestY = output.y < bottom ? bottom : output.y > bottom + TILE_UNITS ? bottom + TILE_UNITS : output.y;
        const deltaX = output.x - nearestX;
        const deltaY = output.y - nearestY;
        if (deltaX * deltaX + deltaY * deltaY >= radius * radius) continue;
        // Resolve along the shallower axis, which is the face the circle came
        // through. Ties resolve on x, deterministically.
        const overlapX = radius - (deltaX < 0 ? -deltaX : deltaX);
        const overlapY = radius - (deltaY < 0 ? -deltaY : deltaY);
        const insideX = output.x > left && output.x < left + TILE_UNITS;
        const insideY = output.y > bottom && output.y < bottom + TILE_UNITS;
        if ((overlapX <= overlapY && !insideX) || insideY) {
          output.x += output.x >= left + TILE_UNITS / 2 ? overlapX : -overlapX;
          output.hitX = true;
        } else {
          output.y += output.y >= bottom + TILE_UNITS / 2 ? overlapY : -overlapY;
          output.hitY = true;
        }
      }
    }
    return output;
  }

  private circleOverlapsSolid(x: number, y: number, radius: number): boolean {
    for (let cellY = cellOfY(y - radius); cellY <= cellOfY(y + radius); cellY += 1) {
      for (let cellX = cellOfX(x - radius); cellX <= cellOfX(x + radius); cellX += 1) {
        if (!this.solidAt(cellX, cellY)) continue;
        const left = WORLD_MIN_X + cellX * TILE_UNITS;
        const bottom = WORLD_MIN_Y + cellY * TILE_UNITS;
        const nearestX = x < left ? left : x > left + TILE_UNITS ? left + TILE_UNITS : x;
        const nearestY = y < bottom ? bottom : y > bottom + TILE_UNITS ? bottom + TILE_UNITS : y;
        if ((x - nearestX) ** 2 + (y - nearestY) ** 2 < radius ** 2) return true;
      }
    }
    return false;
  }

  /**
   * True when nothing solid stands between the two points. A supercover walk over
   * the cell grid, so a diagonal sightline through a wall corner is correctly
   * blocked rather than slipping between two cells.
   */
  lineOfSight(x0: number, y0: number, x1: number, y1: number): boolean {
    let cellX = cellOfX(x0);
    let cellY = cellOfY(y0);
    const endCellX = cellOfX(x1);
    const endCellY = cellOfY(y1);
    if (this.solidAt(cellX, cellY) || this.solidAt(endCellX, endCellY)) return false;
    const deltaX = x1 - x0;
    const deltaY = y1 - y0;
    const stepX = deltaX > 0 ? 1 : deltaX < 0 ? -1 : 0;
    const stepY = deltaY > 0 ? 1 : deltaY < 0 ? -1 : 0;
    const absDeltaX = deltaX < 0 ? -deltaX : deltaX;
    const absDeltaY = deltaY < 0 ? -deltaY : deltaY;
    // Distance from the origin to the first cell boundary on each axis.
    let tMaxX =
      stepX === 0
        ? Number.MAX_SAFE_INTEGER
        : stepX > 0
          ? (WORLD_MIN_X + (cellX + 1) * TILE_UNITS - x0) * absDeltaY
          : (x0 - (WORLD_MIN_X + cellX * TILE_UNITS)) * absDeltaY;
    let tMaxY =
      stepY === 0
        ? Number.MAX_SAFE_INTEGER
        : stepY > 0
          ? (WORLD_MIN_Y + (cellY + 1) * TILE_UNITS - y0) * absDeltaX
          : (y0 - (WORLD_MIN_Y + cellY * TILE_UNITS)) * absDeltaX;
    const tDeltaX = stepX === 0 ? Number.MAX_SAFE_INTEGER : TILE_UNITS * absDeltaY;
    const tDeltaY = stepY === 0 ? Number.MAX_SAFE_INTEGER : TILE_UNITS * absDeltaX;
    // The walk is bounded by the Manhattan cell distance, so a degenerate input
    // can never spin here.
    let guard =
      (endCellX > cellX ? endCellX - cellX : cellX - endCellX) +
      (endCellY > cellY ? endCellY - cellY : cellY - endCellY) +
      2;
    while (guard > 0 && (cellX !== endCellX || cellY !== endCellY)) {
      guard -= 1;
      if (tMaxX <= tMaxY) {
        cellX += stepX;
        tMaxX += tDeltaX;
      } else {
        cellY += stepY;
        tMaxY += tDeltaY;
      }
      if (this.solidAt(cellX, cellY)) return false;
    }
    return true;
  }

  /**
   * Finds the farthest immediately visible waypoint on a shortest open-cell
   * route. The search is breadth-first because every tank traversal edge has
   * the same cost; deterministic neighbour rotation lets roster slots choose
   * different equal-cost corridors without random state or heap allocation.
   * Returns the route length in cells, or `-1` when the goal is unreachable.
   */
  routeWaypoint(
    startX: number,
    startY: number,
    goalX: number,
    goalY: number,
    routeBias: number,
    scratch: ArenaRouteScratch,
    output: WorldPoint,
  ): number {
    const startCellX = cellOfX(startX);
    const startCellY = cellOfY(startY);
    const goalCellX = cellOfX(goalX);
    const goalCellY = cellOfY(goalY);
    if (this.solidAt(startCellX, startCellY) || this.solidAt(goalCellX, goalCellY)) return -1;
    const start = this.index(startCellX, startCellY);
    const goal = this.index(goalCellX, goalCellY);
    if (start === goal || this.lineOfSight(startX, startY, goalX, goalY)) {
      output.x = goalX;
      output.y = goalY;
      return 0;
    }

    scratch.generation = (scratch.generation + 1) >>> 0;
    if (scratch.generation === 0) {
      scratch.visited.fill(0);
      scratch.generation = 1;
    }
    const generation = scratch.generation;
    let read = 0;
    let write = 0;
    scratch.frontier[write++] = start;
    scratch.visited[start] = generation;
    scratch.parent[start] = -1;
    let found = false;
    const bias = routeBias & 3;
    while (read < write && !found) {
      const cell = scratch.frontier[read++]!;
      const x = cell % MAP_WIDTH;
      const y = Math.trunc(cell / MAP_WIDTH);
      for (let step = 0; step < 4; step += 1) {
        const direction = (step + bias) & 3;
        const nextX = x + (direction === 0 ? 1 : direction === 2 ? -1 : 0);
        const nextY = y + (direction === 1 ? 1 : direction === 3 ? -1 : 0);
        if (nextX < 0 || nextY < 0 || nextX >= MAP_WIDTH || nextY >= MAP_HEIGHT) continue;
        if (this.solidAt(nextX, nextY)) continue;
        const next = this.index(nextX, nextY);
        if (scratch.visited[next] === generation) continue;
        scratch.visited[next] = generation;
        scratch.parent[next] = cell;
        scratch.frontier[write++] = next;
        if (next === goal) {
          found = true;
          break;
        }
      }
    }
    if (!found) return -1;

    let cursor = goal;
    let routeLength = 0;
    let waypoint = goal;
    let haveWaypoint = false;
    while (cursor !== start && routeLength < MAP_CELLS) {
      const cellX = cursor % MAP_WIDTH;
      const cellY = Math.trunc(cursor / MAP_WIDTH);
      const candidateX = cellCentreX(cellX);
      const candidateY = cellCentreY(cellY);
      if (!haveWaypoint && this.lineOfSight(startX, startY, candidateX, candidateY)) {
        waypoint = cursor;
        haveWaypoint = true;
      }
      cursor = scratch.parent[cursor]!;
      routeLength += 1;
      if (cursor < 0) return -1;
    }
    output.x = cellCentreX(waypoint % MAP_WIDTH);
    output.y = cellCentreY(Math.trunc(waypoint / MAP_WIDTH));
    return routeLength;
  }

  /** Nearest open cell centre to a world point, searched in rings. */
  nearestOpen(x: number, y: number, output: WorldPoint, clearanceRadius = 0): WorldPoint {
    const originX = cellOfX(x);
    const originY = cellOfY(y);
    const clearance: CircleResolution | undefined =
      clearanceRadius > 0 ? { x: 0, y: 0, hitX: false, hitY: false } : undefined;
    for (let ring = 0; ring < 24; ring += 1) {
      for (let offsetY = -ring; offsetY <= ring; offsetY += 1) {
        for (let offsetX = -ring; offsetX <= ring; offsetX += 1) {
          if (ring > 0 && offsetX !== -ring && offsetX !== ring && offsetY !== -ring && offsetY !== ring) continue;
          const cellX = originX + offsetX;
          const cellY = originY + offsetY;
          if (this.solidAt(cellX, cellY)) continue;
          if (this.solidAt(cellX - 1, cellY) && this.solidAt(cellX + 1, cellY)) continue;
          const centreX = cellCentreX(cellX);
          const centreY = cellCentreY(cellY);
          if (clearance) {
            this.resolveCircle(centreX, centreY, clearanceRadius, clearance);
            if (clearance.x !== centreX || clearance.y !== centreY) continue;
          }
          output.x = centreX;
          output.y = centreY;
          return output;
        }
      }
    }
    if (clearanceRadius > 0) throw new Error(`No open circle of radius ${clearanceRadius} near ${x},${y}`);
    output.x = 0;
    output.y = 0;
    return output;
  }

  /** Count of open cells; used by the tests to assert the arena is not a maze. */
  openCellCount(): number {
    let open = 0;
    for (let index = 0; index < MAP_CELLS; index += 1) if (this.cells[index] === CELL_FLOOR) open += 1;
    return open;
  }

  private build(): void {
    this.cells.fill(CELL_FLOOR);
    // `solidAt` is used while placing spawns and pickups, before the mutable
    // cover table is populated. Keep every cell explicitly static until the
    // deterministic panel pass below assigns the crate/sandbag entries.
    this.coverPanelByCell.fill(-1);
    this.coverHealth.fill(0);
    for (let cellY = 0; cellY < MAP_HEIGHT; cellY += 1) {
      for (let cellX = 0; cellX < MAP_WIDTH; cellX += 1) {
        if (cellX < BORDER || cellY < BORDER || cellX >= MAP_WIDTH - BORDER || cellY >= MAP_HEIGHT - BORDER) {
          this.cells[this.index(cellX, cellY)] = CELL_WALL;
        }
      }
    }

    const marginX = Math.floor((MAP_WIDTH - LATTICE_COLUMNS * LATTICE) / 2) + Math.floor(LATTICE / 2);
    const marginY = Math.floor((MAP_HEIGHT - LATTICE_ROWS * LATTICE) / 2) + Math.floor(LATTICE / 2);
    const points = LATTICE_COLUMNS * LATTICE_ROWS;
    let coverCellsRemaining = MAX_COVER_PANELS;
    for (let point = 0; point < points; point += 1) {
      const column = point % LATTICE_COLUMNS;
      const row = Math.floor(point / LATTICE_COLUMNS);
      const roll = mix32(this.seed, point * 2_654_435_761);
      const stamp = STAMPS[roll % STAMPS.length];
      if (stamp === undefined) continue;
      const footprint = stamp.width * stamp.height;
      if (footprint > coverCellsRemaining) continue;
      const jitterX = mixRange(this.seed ^ 0x51ed_2701, point, 5) - 2;
      const jitterY = mixRange(this.seed ^ 0x2f1b_9a33, point, 5) - 2;
      if (this.stamp(marginX + column * LATTICE + jitterX, marginY + row * LATTICE + jitterY, stamp)) {
        coverCellsRemaining -= footprint;
      }
    }

    // A few valid islands miss every sparse lattice offer. Keep one small
    // destructible encounter in those matches without changing successful
    // layouts or relaxing the shoreline/start/prop clearance rules.
    if (coverCellsRemaining === MAX_COVER_PANELS) {
      const first = mix32(this.seed ^ 0x434f_5645, 0) % MAP_CELLS;
      const crate = STAMPS[5]!;
      for (let candidate = 0; candidate < MAP_CELLS; candidate += 1) {
        const cell = (first + candidate) % MAP_CELLS;
        if (this.stamp(cell % MAP_WIDTH, Math.floor(cell / MAP_WIDTH), crate)) {
          coverCellsRemaining -= crate.width * crate.height;
          break;
        }
      }
    }

    // The same bounded hex plan that paints the floor decides where ocean and
    // grounded scenery block movement. The cover clearance check above means
    // this pass cannot clip a cover stamp into an impassable coastal sliver.
    for (let index = 0; index < MAP_CELLS; index += 1) {
      if (this.plan.cellLand[index] === 0 || this.plan.propSolid[index] !== 0) {
        this.cells[index] = CELL_WALL;
      } else if (this.plan.reserved[index] !== 0) {
        this.cells[index] = CELL_FLOOR;
      }
    }

    this.placeSpawnPoints();
    this.placePickupPads();
    this.placeHazards();
    this.placeDestructibleCover();
  }

  private stamp(centreX: number, centreY: number, stamp: Stamp): boolean {
    const width = stamp.width;
    const height = stamp.height;
    const left = centreX - (width >> 1);
    const bottom = centreY - (height >> 1);
    // Two open cells around every cover stamp keep a driving lane between it
    // and the ocean, scenic colliders or other cover. Reserved starts only
    // exclude the stamp footprint: their surrounding cells are open floor.
    const clearance = 2;
    for (let cellY = bottom - clearance; cellY < bottom + height + clearance; cellY += 1) {
      for (let cellX = left - clearance; cellX < left + width + clearance; cellX += 1) {
        if (cellX < BORDER || cellY < BORDER || cellX >= MAP_WIDTH - BORDER || cellY >= MAP_HEIGHT - BORDER) {
          return false;
        }
        const index = this.index(cellX, cellY);
        if (this.plan.cellLand[index] === 0 || this.plan.propSolid[index] !== 0 || this.cells[index] !== CELL_FLOOR) {
          return false;
        }
      }
    }
    for (let offsetY = 0; offsetY < height; offsetY += 1) {
      for (let offsetX = 0; offsetX < width; offsetX += 1) {
        if (this.plan.reserved[this.index(left + offsetX, bottom + offsetY)] !== 0) return false;
      }
    }
    for (let offsetY = 0; offsetY < height; offsetY += 1) {
      for (let offsetX = 0; offsetX < width; offsetX += 1) {
        const cellX = left + offsetX;
        const cellY = bottom + offsetY;
        this.cells[this.index(cellX, cellY)] = stamp.cell;
      }
    }
    return true;
  }

  private placeSpawnPoints(): void {
    const clear: CircleResolution = { x: 0, y: 0, hitX: false, hitY: false };
    for (let index = 0; index < SPAWN_POINT_COUNT; index += 1) {
      const cell = this.plan.spawnCells[index]!;
      const cellX = cell % MAP_WIDTH;
      const cellY = Math.floor(cell / MAP_WIDTH);
      const worldX = cellCentreX(cellX);
      const worldY = cellCentreY(cellY);
      this.resolveCircle(worldX, worldY, PLAYER_RADIUS, clear);
      if (clear.x !== worldX || clear.y !== worldY) throw new Error(`planned spawn ${index} is blocked`);
      this.spawnX[index] = worldX;
      this.spawnY[index] = worldY;
    }
    for (let index = 0; index < WORLD_PLAN_START_COUNT; index += 1) {
      const cell = this.plan.playerStartCells[index]!;
      const worldX = cellCentreX(cell % MAP_WIDTH);
      const worldY = cellCentreY(Math.floor(cell / MAP_WIDTH));
      this.resolveCircle(worldX, worldY, PLAYER_RADIUS, clear);
      if (clear.x !== worldX || clear.y !== worldY) throw new Error(`planned player start ${index} is blocked`);
      this.playerStartX[index] = worldX;
      this.playerStartY[index] = worldY;
    }
  }

  private placePickupPads(): void {
    // Kinds alternate on a fixed cycle; pickup pads are moved to a clear cell
    // after the island and cover plan have been applied.
    const cycle = [
      WEAPON_AUTOCANNON,
      PICKUP_HEALTH,
      WEAPON_SCATTER,
      PICKUP_ARMOR,
      WEAPON_RICOCHET,
      PICKUP_HEALTH,
      WEAPON_MORTAR,
      PICKUP_ARMOR,
      WEAPON_AUTOCANNON,
      PICKUP_HEALTH,
      WEAPON_SCATTER,
      PICKUP_OVERDRIVE,
      WEAPON_RICOCHET,
      PICKUP_HEALTH,
      WEAPON_RAILGUN,
      PICKUP_ARMOR,
    ];
    const point: WorldPoint = { x: 0, y: 0 };
    const columns = 8;
    const rows = MAX_PICKUPS / columns;
    for (let index = 0; index < MAX_PICKUPS; index += 1) {
      const column = index % columns;
      const row = Math.floor(index / columns);
      const cellX = Math.round(BORDER + 8 + (column / (columns - 1)) * (MAP_WIDTH - 2 * BORDER - 17));
      const cellY = Math.round(BORDER + 9 + (row / (rows - 1)) * (MAP_HEIGHT - 2 * BORDER - 19));
      this.nearestOpen(cellCentreX(cellX), cellCentreY(cellY), point, PLAYER_RADIUS);
      this.pickupX[index] = point.x;
      this.pickupY[index] = point.y;
      this.pickupKind[index] = cycle[index % cycle.length]!;
    }
  }

  private placeHazards(): void {
    // Keep the vents away from the central command beacon. They are derived
    // content, not mutable terrain state.
    const cells = [
      [30, 22],
      [MAP_WIDTH - 1 - 30, 22],
      [30, MAP_HEIGHT - 1 - 22],
      [MAP_WIDTH - 1 - 30, MAP_HEIGHT - 1 - 22],
    ] as const;
    const point: WorldPoint = { x: 0, y: 0 };
    for (let index = 0; index < MAX_HAZARDS; index += 1) {
      this.nearestOpen(cellCentreX(cells[index]![0]), cellCentreY(cells[index]![1]), point, PLAYER_RADIUS);
      this.hazardX[index] = point.x;
      this.hazardY[index] = point.y;
    }
  }

  private placeDestructibleCover(): void {
    this.coverPanelByCell.fill(-1);
    this.coverHealth.fill(0);
    let panel = 0;
    for (let cellY = BORDER; cellY < MAP_HEIGHT - BORDER && panel < MAX_COVER_PANELS; cellY += 1) {
      for (let cellX = BORDER; cellX < MAP_WIDTH - BORDER && panel < MAX_COVER_PANELS; cellX += 1) {
        const cell = this.index(cellX, cellY);
        if (this.cells[cell] !== CELL_CRATE && this.cells[cell] !== CELL_SANDBAG) continue;
        this.coverPanelByCell[cell] = panel;
        this.coverX[panel] = cellCentreX(cellX);
        this.coverY[panel] = cellCentreY(cellY);
        this.coverHealth[panel] = COVER_MAX_HEALTH;
        panel += 1;
      }
    }
    this.coverPanelCount = panel;
  }
}
